mapper.select:
SELECT j.*, h.start, h.`end`, h.starttime, h.place, h.price, h.duration, c.company_name, u.name AS user_name, cb.cabin_name, cb.cabin_class FROM jpdd j LEFT JOIN hbxx h ON j.hbid = h.hbid LEFT JOIN company c ON h.company_id = c.company_id LEFT JOIN `user` u ON j.userid = u.id LEFT JOIN hbxx_cabin cb ON j.cabin_id = cb.cabin_id WHERE j.userid = #{userid}
AND j.status = #{status}
ORDER BY j.ordertime DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM jpdd
WHERE userid = #{userid}

    AND status = #{status}
